const visual = {
  prepare: function (input) {
    var texts = [
      'F(x) = F₀(1 − x/h),  0 ≤ x ≤ h',
      'F(x)',
      'x',
      '0',
      'h/2',
      'h',
      'F₀',
      '阴影面积 W',
      'W = 3/8 F₀h',
      'W/(F₀h) = 3/8 = 0.375'
    ];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var ox = Math.max(88, W * 0.14);
    var oy = H - Math.max(70, H * 0.16);
    var xEnd = W - Math.max(64, W * 0.09);
    var yTop = Math.max(72, H * 0.16);
    var hx = xEnd;
    var midX = ox + (hx - ox) / 2;
    var f0Y = yTop;
    var midY = (f0Y + oy) / 2;
    var axisX = visualSdk.arrow(ox, oy, xEnd + 18, oy, { head: 7 });
    var axisY = visualSdk.arrow(ox, oy, ox, yTop - 22, { head: 7 });
    var curve = visualSdk.polyline([[ox, f0Y], [hx, oy]]);
    var shadeCmds = ['M', ox, oy, 'L', ox, f0Y, 'L', midX, midY, 'L', midX, oy, 'Z'];
    var midGuide = visualSdk.polyline([[midX, midY], [midX, oy]]);
    var tickH = visualSdk.polyline([[hx, oy - 5], [hx, oy + 5]]);
    var tickMid = visualSdk.polyline([[midX, oy - 5], [midX, oy + 5]]);
    var tickF0 = visualSdk.polyline([[ox - 5, f0Y], [ox + 5, f0Y]]);
    var dot = visualSdk.circle(midX, midY, 3.5);
    var dotOrigin = visualSdk.circle(ox, oy, 2.5);

    return {
      schemaVersion: 1,
      sceneId: 'f-over-h-shaded-area',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'shade', commands: shadeCmds },
        { id: 'axisX', commands: axisX },
        { id: 'axisY', commands: axisY },
        { id: 'curve', commands: curve },
        { id: 'midGuide', commands: midGuide },
        { id: 'tickH', commands: tickH },
        { id: 'tickMid', commands: tickMid },
        { id: 'tickF0', commands: tickF0 },
        { id: 'dotMid', commands: dot },
        { id: 'dotOrigin', commands: dotOrigin }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'shade', fill: '#9ecae1', stroke: 'none', opacity: 0.55 },
        { type: 'path', pathId: 'axisX', stroke: '#26354a', strokeWidth: 1.8, fill: 'none' },
        { type: 'path', pathId: 'axisY', stroke: '#26354a', strokeWidth: 1.8, fill: 'none' },
        { type: 'path', pathId: 'midGuide', stroke: '#6b7c93', strokeWidth: 1.2, strokeDasharray: [5, 4], fill: 'none' },
        { type: 'path', pathId: 'curve', stroke: '#c0392b', strokeWidth: 3, fill: 'none' },
        { type: 'path', pathId: 'tickH', stroke: '#26354a', strokeWidth: 1.6 },
        { type: 'path', pathId: 'tickMid', stroke: '#26354a', strokeWidth: 1.6 },
        { type: 'path', pathId: 'tickF0', stroke: '#26354a', strokeWidth: 1.6 },
        { type: 'path', pathId: 'dotMid', fill: '#c0392b', stroke: '#c0392b' },
        { type: 'path', pathId: 'dotOrigin', fill: '#26354a', stroke: '#26354a' },
        { type: 'label', x: W/2, y: 34, text: 'F(x) = F₀(1 − x/h),  0 ≤ x ≤ h', fontSize: 18, fill: '#1f2d3d', textAnchor: 'middle' },
        { type: 'label', x: ox - 16, y: f0Y + 5, text: 'F₀', fontSize: 15, fill: '#26354a', textAnchor: 'end' },
        { type: 'label', x: ox - 16, y: oy + 5, text: '0', fontSize: 15, fill: '#26354a', textAnchor: 'end' },
        { type: 'label', x: midX, y: oy + 24, text: 'h/2', fontSize: 15, fill: '#26354a', textAnchor: 'middle' },
        { type: 'label', x: hx, y: oy + 24, text: 'h', fontSize: 15, fill: '#26354a', textAnchor: 'middle' },
        { type: 'label', x: xEnd + 24, y: oy + 5, text: 'x', fontSize: 16, fill: '#26354a', textAnchor: 'start' },
        { type: 'label', x: ox + 8, y: yTop - 28, text: 'F(x)', fontSize: 16, fill: '#26354a', textAnchor: 'start' },
        { type: 'label', x: (ox + midX)/2, y: (f0Y + midY)/2 + 24, text: '阴影面积 W', fontSize: 15, fill: '#1f4e79', textAnchor: 'middle' },
        { type: 'label', x: W - 34, y: H - 46, text: 'W = 3/8 F₀h', fontSize: 16, fill: '#1f4e79', textAnchor: 'end' },
        { type: 'label', x: W - 34, y: H - 24, text: 'W/(F₀h) = 3/8 = 0.375', fontSize: 16, fill: '#1f4e79', textAnchor: 'end' }
      ] }
    };
  }
};
